@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul>
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")" @onclick="() => OnSectionSelected.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                <span class="sidebar-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings
@using sv_882c29be2fd44fc7b526b516abff9dab.Models

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (Profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@avatarUrl" alt="Avatar" class="avatar-image" />
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="avatarUrl" @bind:event="oninput" />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="displayName" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="email" @bind:event="oninput" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="bio" @bind:event="oninput"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
                <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Profile saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private bool showSuccess;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            LoadFromProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void LoadFromProfile()
    {
        displayName = Profile!.DisplayName;
        email = Profile.Email;
        avatarUrl = Profile.AvatarUrl;
        bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(displayName, email, avatarUrl, bio);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        StateHasChanged();
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }

    private void Discard()
    {
        LoadFromProfile();
        showSuccess = false;
    }
}

@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings
@using sv_882c29be2fd44fc7b526b516abff9dab.Models

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (Prefs is not null)
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" checked="@emailNotifications" @onchange="e => emailNotifications = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" checked="@pushNotifications" @onchange="e => pushNotifications = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" checked="@weeklyDigest" @onchange="e => weeklyDigest = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="channels-section">
                <h3>Channel Muting</h3>
                <p class="hint">Check channels you want to mute:</p>
                <div class="channel-list">
                    @foreach (var channel in channels)
                    {
                        <label class="channel-item">
                            <input type="checkbox" checked="@mutedChannels.Contains(channel)" @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <span>#@channel</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> channels = new();
    private HashSet<string> mutedChannels = new();
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            channels = new List<string>(Prefs.MutedChannels);
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings
@using sv_882c29be2fd44fc7b526b516abff9dab.Models

<div class="settings-section">
    <h2>Security Settings</h2>

    @if (Settings is not null)
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => passwordPanelOpen = !passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="currentPassword" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="newPassword" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="confirmPassword" />
                    </div>
                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="toast error">@passwordError</div>
                    }
                    @if (passwordSuccess)
                    {
                        <div class="toast success">Password updated successfully!</div>
                    }
                    <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="security-item">
            <div class="security-item-info">
                <h3>Two-Factor Authentication</h3>
                <span class="status-indicator @(twoFactorEnabled ? "enabled" : "disabled")">
                    @(twoFactorEnabled ? "✓ Enabled" : "✗ Disabled")
                </span>
            </div>
            <label class="switch">
                <input type="checkbox" checked="@twoFactorEnabled" @onchange="e => twoFactorEnabled = (bool)e.Value!" />
                <span class="slider"></span>
            </label>
        </div>

        @if (Settings.LastPasswordChange.HasValue)
        {
            <p class="hint">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }

        <!-- Active Sessions -->
        <div class="sessions-section">
            <h3>Active Sessions</h3>
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">Revoke</button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="dialog-overlay" @onclick="CancelRevoke">
                <div class="dialog" @onclick:stopPropagation="true">
                    <h3>Revoke Session</h3>
                    <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                    <div class="dialog-actions">
                        <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    </div>
                </div>
            </div>
        }
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }
    [Parameter] public string CurrentSessionId { get; set; } = "session-1";

    private bool passwordPanelOpen;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? passwordError;
    private bool passwordSuccess;
    private bool twoFactorEnabled;
    private ActiveSession? sessionToRevoke;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            twoFactorEnabled = Settings.TwoFactorEnabled;
            hasInitialized = true;
        }
    }

    private async Task ChangePasswordAsync()
    {
        passwordError = null;
        passwordSuccess = false;

        if (string.IsNullOrWhiteSpace(currentPassword))
        {
            passwordError = "Current password is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(newPassword) || newPassword.Length < 8)
        {
            passwordError = "New password must be at least 8 characters.";
            return;
        }
        if (newPassword != confirmPassword)
        {
            passwordError = "Passwords do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((currentPassword, newPassword));
        passwordSuccess = true;
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
    }

    private void PromptRevoke(ActiveSession session) => sessionToRevoke = session;
    private void CancelRevoke() => sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(sessionToRevoke.Id);
            sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings
@using sv_882c29be2fd44fc7b526b516abff9dab.Models

<div class="settings-section">
    <h2>Appearance</h2>

    @if (Settings is not null)
    {
        <div class="appearance-form">
            <!-- Theme -->
            <div class="form-group">
                <label><strong>Theme</strong></label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="theme" value="@theme" checked="@(selectedTheme == theme)" @onchange="() => selectedTheme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="form-group">
                <label><strong>Font Size</strong></label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <label class="radio-label">
                            <input type="radio" name="fontSize" value="@size" checked="@(selectedFontSize == size)" @onchange="() => selectedFontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="form-group">
                <label for="language"><strong>Language</strong></label>
                <select id="language" @bind="selectedLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <!-- Compact Mode -->
            <div class="form-group">
                <label class="toggle-label">
                    <span><strong>Compact Mode</strong></span>
                    <label class="switch">
                        <input type="checkbox" checked="@compactMode" @onchange="e => compactMode = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <!-- Live Preview -->
            <div class="preview-area @GetPreviewClasses()">
                <h4>Live Preview</h4>
                <div class="preview-content">
                    <p class="preview-heading">Sample Heading</p>
                    <p class="preview-text">This is how your content will look with the selected appearance settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "English";
    private bool compactMode;
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{selectedTheme.ToLower()} font-{selectedFontSize.ToLower()}";
        if (compactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

