@namespace sv_882c29be2fd44fc7b526b516abff9dab.Components.Pages.Settings
@using sv_882c29be2fd44fc7b526b516abff9dab.Models

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (Prefs is not null)
    {
        <div class="notification-form">
            <div class="toggle-group">
                <label class="toggle-label">
                    <span>Email Notifications</span>
                    <label class="switch">
                        <input type="checkbox" checked="@emailNotifications" @onchange="e => emailNotifications = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Push Notifications</span>
                    <label class="switch">
                        <input type="checkbox" checked="@pushNotifications" @onchange="e => pushNotifications = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>

                <label class="toggle-label">
                    <span>Weekly Digest</span>
                    <label class="switch">
                        <input type="checkbox" checked="@weeklyDigest" @onchange="e => weeklyDigest = (bool)e.Value!" />
                        <span class="slider"></span>
                    </label>
                </label>
            </div>

            <div class="channels-section">
                <h3>Channel Muting</h3>
                <p class="hint">Check channels you want to mute:</p>
                <div class="channel-list">
                    @foreach (var channel in channels)
                    {
                        <label class="channel-item">
                            <input type="checkbox" checked="@mutedChannels.Contains(channel)" @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                            <span>#@channel</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAsync">Save Preferences</button>
            </div>

            @if (showSuccess)
            {
                <div class="toast success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public NotificationPrefs? Prefs { get; set; }
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private List<string> channels = new();
    private HashSet<string> mutedChannels = new();
    private bool showSuccess;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            channels = new List<string>(Prefs.MutedChannels);
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            hasInitialized = true;
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        showSuccess = true;
        _ = HideToastAfterDelay();
    }

    private async Task HideToastAfterDelay()
    {
        await Task.Delay(3000);
        showSuccess = false;
        await InvokeAsync(StateHasChanged);
    }
}

