+}
+
+.security-item {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    max-width: 400px;
+    padding: 1rem 0;
+    margin-bottom: 0.5rem;
+}
+
+.security-item-info h3 {
+    margin: 0 0 0.25rem 0;
+    font-size: 1rem;
+}
+
+.status-indicator {
+    font-size: 0.85rem;
+    font-weight: 500;
+}
+
+.status-indicator.enabled {
+    color: #2e7d32;
+}
+
+.status-indicator.disabled {
+    color: #d32f2f;
+}
+
+/* Sessions Table */
+.sessions-section {
+    margin-top: 1.5rem;
+}
+
+.sessions-section h3 {
+    margin-bottom: 0.75rem;
+}
+
+.sessions-table {
+    width: 100%;
+    border-collapse: collapse;
+    font-size: 0.9rem;
+}
+
+.sessions-table th,
+.sessions-table td {
+    padding: 0.6rem 0.75rem;
+    text-align: left;
+    border-bottom: 1px solid #e0e0e0;
+}
+
+.sessions-table th {
+    background: #f8f9fa;
+    font-weight: 600;
+    color: #555;
+}
+
+.current-badge {
+    font-size: 0.8rem;
+    background: #e8f5e9;
+    color: #2e7d32;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+}
+
+/* Dialog */
+.dialog-overlay {
+    position: fixed;
+    top: 0;
+    left: 0;
+    right: 0;
+    bottom: 0;
+    background: rgba(0, 0, 0, 0.5);
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    z-index: 1000;
+}
+
+.dialog {
+    background: #fff;
+    border-radius: 12px;
+    padding: 2rem;
+    max-width: 420px;
+    width: 90%;
+    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
+}
+
+.dialog h3 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.5rem;
+    justify-content: flex-end;
+}
+
+/* Appearance */
+.radio-group {
+    display: flex;
+    gap: 1.5rem;
+    margin-top: 0.25rem;
+}
+
+.radio-label {
+    display: flex;
+    align-items: center;
+    gap: 0.4rem;
+    cursor: pointer;
+}
+
+/* Preview Area */
+.preview-area {
+    margin-top: 2rem;
+    padding: 1.5rem;
+    border: 2px dashed #ccc;
+    border-radius: 8px;
+    transition: all 0.3s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+    margin-bottom: 1rem;
+    color: #666;
+    font-size: 0.85rem;
+    text-transform: uppercase;
+    letter-spacing: 0.05em;
+}
+
+.preview-content {
+    padding: 1rem;
+    border-radius: 6px;
+    transition: all 0.3s;
+}
+
+.preview-area.theme-light .preview-content {
+    background: #ffffff;
+    color: #333;
+    border: 1px solid #e0e0e0;
+}
+
+.preview-area.theme-dark .preview-content {
+    background: #1e1e1e;
+    color: #e0e0e0;
+    border: 1px solid #444;
+}
+
+.preview-area.theme-system .preview-content {
+    background: #f0f0f0;
+    color: #333;
+    border: 1px solid #ccc;
+}
+
+.preview-area.font-small .preview-content {
+    font-size: 0.8rem;
+}
+
+.preview-area.font-medium .preview-content {
+    font-size: 1rem;
+}
+
+.preview-area.font-large .preview-content {
+    font-size: 1.2rem;
+}
+
+.preview-area.compact .preview-content {
+    padding: 0.5rem;
+    line-height: 1.3;
+}
+
+.preview-heading {
+    font-weight: 600;
+    margin-bottom: 0.5rem;
+}
+
+.preview-text {
+    margin-bottom: 0.75rem;
+    opacity: 0.85;
+}
+
+.preview-button {
+    padding: 0.4rem 1rem;
+    border: none;
+    border-radius: 4px;
+    background: #1976d2;
+    color: #fff;
+    font-size: inherit;
+    cursor: default;
+}
+
+.preview-area.theme-dark .preview-button {
+    background: #64b5f6;
+    color: #1e1e1e;
+}
+
+/* Toast */
+.toast {
+    margin-top: 1rem;
+    padding: 0.75rem 1rem;
+    border-radius: 6px;
+    font-size: 0.9rem;
+    animation: slideIn 0.3s ease;
+}
+
+.toast.success {
+    background: #e8f5e9;
+    color: #2e7d32;
+    border: 1px solid #a5d6a7;
+}
+
+.toast.error {
+    background: #ffebee;
+    color: #c62828;
+    border: 1px solid #ef9a9a;
+}
+
+@keyframes slideIn {
+    from {
+        opacity: 0;
+        transform: translateY(-10px);
+    }
+    to {
+        opacity: 1;
+        transform: translateY(0);
+    }
+}
+

